#include "qdcoop/object_lookup.hpp"
#include <array>
#include <cassert>
#include <cstdio>
#include <cstring>
namespace U=qdcoop::ue427;
int main(){std::array<unsigned char,200000> memory{};auto read=[&](std::uintptr_t p,void* out,std::size_t n){if(p>memory.size()||n>memory.size()-p)return false;std::memcpy(out,memory.data()+p,n);return true;};auto put=[&](auto p,auto value){std::memcpy(memory.data()+p,&value,sizeof(value));};put(1008,std::uint32_t{0});put(1012,std::uint32_t{64});put(1016,std::uintptr_t{2000});put(2000,std::uint16_t{4<<6});std::memcpy(memory.data()+2002,"None",4);std::string out;assert(U::name_string(1000,{0,0},read,out)&&out=="None");assert(U::name_string(1000,{0,42},read,out)&&out=="None_41");put(2010,std::uint16_t{(3<<6)|1});put(2012,std::uint16_t{0x4e2d});put(2014,std::uint16_t{0xd83d});put(2016,std::uint16_t{0xde00});assert(U::name_string(1000,{5,0},read,out)&&out=="\xe4\xb8\xad\xf0\x9f\x98\x80");put(2016,std::uint16_t{0x41});assert(!U::name_string(1000,{5,0},read,out)&&out.empty());assert(!U::name_string(1000,{65536,0},read,out));put(1012,std::uint32_t{4});assert(!U::name_string(1000,{0,0},read,out));put(1008,std::uint32_t{8192});assert(!U::name_string(1000,{0,0},read,out));put(1008,std::uint32_t{0});put(1012,std::uint32_t{64});put(30024,U::NameKey{0,0});put(30124,U::NameKey{0,2});put(30132,std::uintptr_t{30000});assert(U::object_path(30100,1000,read,out)&&out=="None.None_1");put(30032,std::uintptr_t{30100});assert(!U::object_path(30100,1000,read,out));put(30032,std::uintptr_t{});put(30080,std::uintptr_t{31000});put(31040,U::NameKey{0,0});assert(U::find_property(30000,1000,"None",read)==31000);put(31032,std::uintptr_t{31000});assert(!U::find_property(30000,1000,"missing",read));put(30164,std::uintptr_t{30000});assert(U::find_inherited_property(30100,1000,"None",read)==31000);put(30064,std::uintptr_t{30100});assert(!U::find_inherited_property(30100,1000,"missing",read));std::puts("PASS name pool bounds, numbered names, ASCII, UTF16 surrogates, malformed entries, object paths/cycles and inherited fields");}
